const iconMap = { BookOpen, Feather, Clapperboard, ScanText, Lightbulb, ListTree, UsersRound, WandSparkles, MessagesSquare, Type };
const navItems = [
 { id:'home', label:'首页', icon:LayoutDashboard },
 { id:'works', label:'我的作品', icon:FolderOpen },
  { id:'novels', label:'小说写作', icon:BookOpen, section:'创作功能', nested:true },
 { id:'scripts', label:'剧本创作', icon:Clapperboard, nested:true },
 ...(videoEnabled?[{ id:'video', label:'漫剧工坊', icon:Play, nested:true }]:[]),
 { id:'dismantle', label:'小说拆书', icon:BookMarked, nested:true },
 { id:'tools', label:'写作工具', icon:Sparkles, section:'创作辅助', nested:true },
 { id:'workflows', label:'创作工作流', icon:Workflow, nested:true },
 { id:'history',label:'生成记录',icon:Clock3,section:'创作记录' },
 { id:'submit', label:'投稿中心', icon:Send, section:'创作服务' },
 { id:'learn', label:'写作课堂', icon:GraduationCap },
 { id:'membership', label:'会员与墨点', icon:Crown }
];
function useStored(key,fallback){return useCollection(key.replace(/^mdd-|-v1$/g,''),fallback);}
const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
const cn = (...classes) => classes.filter(Boolean).join(' ');
function Icon({ name, ...props }) { const Component = iconMap[name] || Sparkles; return <Component {...props}/>; }
function Empty({ title, text, action }) { return <div className="empty-state"><Feather size={36}/><h3>{title}</h3><p>{text}</p>{action}</div>; }

export function App() { return <AccountProvider><WorkspaceProvider><GenerationProvider><BillingProvider><WritingApp/></BillingProvider></GenerationProvider></WorkspaceProvider></AccountProvider>; }

export function WritingApp() {
 const billing=useBilling(),workspace=useWorkspace();
 const [route, setRoute] = useState(location.hash.slice(1) || 'home');
 const [allWorks, setWorks, workSaveError] = useStored('mdd-works-v1', initialWorks);
 const worksRef=useRef(allWorks);worksRef.current=allWorks;
 const works=allWorks.filter(work=>!work.deletedAt);
 const trashWorks=allWorks.filter(work=>work.deletedAt);
 const [favorites, setFavorites] = useStored('mdd-favorites-v1', ['ideas', 'polish']);
 const [submissions, setSubmissions] = useStored('mdd-submissions-v1', []);
 const [modal, setModal] = useState(null);const [videoHandoff,setVideoHandoff]=useState(null),[submissionWorkId,setSubmissionWorkId]=useState('');const [workspaceRevision,setWorkspaceRevision]=useState(0);
 useEffect(()=>setModal(null),[billing.navigationKey]);
 const [toast, setToast] = useState('');
 const [search, setSearch] = useState('');
 const toastTimer = useRef();
 const importRef = useRef();
 const notify = message => { setToast(message); clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 3200); };
 const navigate = id => {if(id!=='video')setVideoHandoff(null);if(id!=='submit')setSubmissionWorkId(''); location.hash = id; setRoute(id); window.scrollTo(0,0); };
 useEffect(() => { const change = () => { setRoute(location.hash.slice(1) || 'home'); setModal(null); window.scrollTo(0,0); }; window.addEventListener('hashchange',change); return () => window.removeEventListener('hashchange',change); }, []);
 useEffect(() => { const onKey = event => { if ((event.metaKey || event.ctrlKey) && event.key === 'k') { event.preventDefault(); setModal({ type:'search' }); } if (event.key === 'Escape') { setModal(null); } }; window.addEventListener('keydown',onKey); return () => window.removeEventListener('keydown',onKey); }, []);
 useEffect(() => {
  if(!modal) return;
  const dialog=document.querySelector('.modal');
  if(!dialog) return;
  const previous=document.activeElement;
  const elements=()=>Array.from(dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]')).filter(element=>element.offsetParent!==null);
  const initial=dialog.querySelector('input:not([disabled]),textarea:not([disabled]),select:not([disabled])')||elements()[0];
  const frame=requestAnimationFrame(()=>initial?.focus());
  const trap=event=>{if(event.key!=='Tab')return;const candidates=elements();if(!candidates.length)return;const first=candidates[0],last=candidates.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}};
  dialog.addEventListener('keydown',trap);
  return()=>{cancelAnimationFrame(frame);dialog.removeEventListener('keydown',trap);if(previous?.isConnected)previous.focus();};
 },[modal?.type]);
 const createWork = ({ title, kind, genre, idea = '', outline, characters = '', text = '' }) => {
  const id = uid();
  const work = { id, title, kind, genre, cover: genre === '言情' ? 'spring' : genre === '科幻' ? 'orbit' : 'plain', subtitle:'A NEW STORY BEGINS', description:idea || '每一个故事，都从第一句话开始。', createdAt:new Date().toISOString(), updatedAt:new Date().toISOString(), updated:'刚刚', progress:0, chapters:[{id:uid(), title:kind === '剧本' ? '第一场 · 故事开始' : '第一章 · 故事开始', text}], outline:outline ?? idea, characters };
  setWorks(prev => [work, ...prev]); setModal(null); navigate(`editor/${id}`); notify('新作品已创建，开始你的故事吧');
 };
 const updateWork = work => setWorks(prev => placeRecentlyEdited(prev,work));
 const toggleFavorite = id => { setFavorites(prev => prev.includes(id) ? prev.filter(item => item !== id) : [...prev,id]); };
 const importFile = async event => {try{ const file = event.target.files?.[0]; if (!file) return; if (!/\.txt$/i.test(file.name)) { notify('请导入 TXT 格式的文稿'); return; } const text = await file.text(); if (text.length > 1500000) { notify('请导入小于 150 万字的文稿'); return; } const id = uid(); setWorks(prev => [{ id, title:file.name.replace(/\.txt$/i,''), kind:'长篇小说', genre:'其他', cover:'plain', subtitle:'YOUR OWN STORY', description:'从本地导入的作品', updated:'刚刚', progress:0, chapters:splitManuscript(text), outline:'', characters:'' }, ...prev]); navigate(`editor/${id}`); notify('文稿导入成功'); event.target.value = ''; }catch{notify('文稿读取失败，请检查文件后重试');}finally{event.target.value='';} };
 const openVideo=(work,chapter)=>{setVideoHandoff({workId:work.id,script:chapter?.text||work.chapters.map(c=>c.text).join('\n\n'),title:work.title});navigate('video');};
 const openSubmission=work=>{setSubmissionWorkId(work.id);navigate('submit');};
 const common = { works, navigate, setModal, notify, favorites, openVideo,openSubmission, toggleFavorite, createWork, onImport:() => importRef.current.click(), trashWorks, onRestoreWork:work=>{updateWork({...work,deletedAt:undefined});notify('作品已恢复到书架');} };
 const currentWork = route.startsWith('editor/') && works.find(work => work.id === route.split('/')[1]);
 const modalWork=allWorks.find(work=>work.id===modal?.workId&&!work.deletedAt)||currentWork;
 return <>
  {(workspace?Boolean(workspace.cacheError):workSaveError)&&<div className="storage-error-banner" role="alert"><FileText size={16}/><span>{workspace?.status==='saved'?'当前更改已保存到本地服务，但设备离线缓存未能更新。建议先导出备份。':'设备缓存未能更新，部分更改可能尚未保存。请保持页面打开并导出备份。'}</span>{currentWork&&<button onClick={()=>{downloadText(`${currentWork.title}.txt`,`${currentWork.title}\n\n${currentWork.chapters.map(ch=>`${ch.title}\n\n${ch.text}`).join('\n\n')}`);notify('当前作品已导出');}}>导出当前作品<Download size={14}/></button>}</div>}
  <input type="file" accept=".txt,text/plain" ref={importRef} className="hidden" onChange={importFile}/>
  {currentWork ? <Editor key={currentWork.id} work={currentWork} onChange={updateWork} onBack={() => navigate('works')} notify={notify} setModal={setModal} saveError={workSaveError} openVideo={openVideo} openSubmission={openSubmission}/> : <WorkbenchFrame items={navItems} route={route} navigate={navigate} setModal={setModal} dialogOpen={Boolean(modal)} onSearch={() => {setSearch(''); setModal({type:'search'});}}>
    <main className={cn("main-content",(route==='home'||route==='tools')&&"market-content",route==='home'&&"home-content")} key={`${route}-${workspaceRevision}`}>
     {route === 'home' && <ReferenceHome {...common}/>}
     {route === 'works' && <WorksPage {...common}/> }
     {route === 'novels' && <NovelDesk {...common}/>}
     {route === 'tools' && <ReferenceTools {...common}/>}
     {route === 'workflows' && <WorkflowsPage {...common}/>}
     {route === 'dismantle' && <DismantleDesk {...common}/>}
     {route === 'scripts' && <ScriptDesk {...common}/>}
     {route === 'video' && (videoEnabled?<VideoStudio {...common} initial={videoHandoff}/>:<div className="surface"><Empty title="视频相关功能已暂缓" text="当前版本专注小说、文字剧本与内容编辑，已有资料会保留。" action={<button className="button primary" onClick={()=>navigate('scripts')}>前往文字剧本创作<ArrowRight size={15}/></button>}/></div>)}
     {route === 'submit' && <SubmissionDesk {...common} initialWorkId={submissionWorkId} submissions={submissions} setSubmissions={setSubmissions}/>}
     {route === 'learn' && <LearnPage {...common}/>}
     {route === 'history' && <GenerationHistory {...common} onChange={updateWork}/>}
     {route === 'membership' && <MembershipPage navigate={navigate}/>}
     {route === 'service-admin' && <ServiceAdmin/>}
     {!navItems.some(item => item.id === route) && !['video','service-admin'].includes(route) && <ReferenceHome {...common}/>}
     <footer className="page-footer"><span>墨多多写作</span><i/>让灵感落笔，让故事生长。</footer>
    </main>
  </WorkbenchFrame>}
  {modal && <div className="modal-backdrop" onMouseDown={event => { if(event.target === event.currentTarget) setModal(null); }}><section className={cn('modal',modal.type === 'search' && 'search-modal',modal.type === 'workflow' && 'workflow-modal',modal.type === 'draft-review'&&'draft-review-modal', ['settings','chapters','versions','chapter-plan','story-memory','chapter-queue'].includes(modal.type)&&'wide-modal')} role="dialog" aria-modal="true" aria-label={modal.type === 'create' ? '新建作品' : '墨多多写作'}><button className="modal-close icon-button" aria-label="关闭" onClick={() => setModal(null)}><X size={20}/></button>
   {modal.type === 'settings' && <SettingsDialog works={allWorks} notify={notify} onRestore={data=>{setWorks(data.works);setFavorites(data.favorites);setSubmissions(data.submissions);setWorkspaceRevision(value=>value+1);}}/>}
   {modal.type === 'work-details' && <WorkDetailsDialog work={allWorks.find(w=>w.id===modal.work.id)||modal.work} onSave={work=>{updateWork(work);setModal(null);notify('作品资料已保存');}} onTrash={work=>{updateWork({...work,deletedAt:new Date().toISOString()});setModal(null);if(currentWork)navigate('works');notify('作品已移入回收站，可随时恢复');}}/>}
   {modal.type === 'chapter-plan' && <ChapterPlanner work={allWorks.find(w=>w.id===modal.workId)||currentWork} initialPlans={modal.plans} onChange={updateWork} notify={notify} onClose={()=>setModal(null)} onOpenQueue={work=>setModal({type:'chapter-queue',workId:work.id})}/>}
   {modal.type === 'story-memory' && modalWork && <StoryMemoryPanel work={modalWork} initialExtraction={modal.initialExtraction} extractionText={modal.extractionText} chapterId={modal.chapterId} onChange={updateWork} notify={notify}/>}
   {modal.type === 'chapter-queue' && modalWork && <ChapterQueue work={modalWork} onChange={updateWork} notify={notify} onClose={()=>setModal(null)}/>}
   {modal.type === 'chapters' && <ChapterManager work={currentWork} chapterId={modal.chapterId} onChange={updateWork} notify={notify}/>}
   {modal.type === 'versions' && <VersionDialog work={currentWork} chapterId={modal.chapterId} onChange={updateWork} notify={notify}/>}
   {modal.type === 'create' && <CreateForm initial={modal} onCreate={createWork}/>}
   {modal.type === 'quick-start' && <QuickStartDialog initial={modal} createWork={createWork}/>}
   {modal.type === 'draft-review' && <DraftReviewDialog {...modal}/>}
   {modal.type === 'tool' && <ToolDialog getWork={id=>worksRef.current.find(work=>work.id===id&&!work.deletedAt)} tool={modal.tool} works={works} onFavorite={() => toggleFavorite(modal.tool.id)} favorite={favorites.includes(modal.tool.id)} initial={modal} createWork={createWork} notify={notify} setModal={setModal} onChange={updateWork}/>}
   {modal.type === 'workflow' && <WorkflowDialog flow={modal.flow} works={works} createWork={createWork} initial={modal} onChange={updateWork} setModal={setModal} notify={notify}/>}
   {modal.type === 'search' && <><div className="search-dialog-input"><Search size={22}/><input autoFocus placeholder="查找你的作品、写作工具和工作流…" value={search} onChange={e => setSearch(e.target.value)}/><kbd>ESC</kbd></div><div className="search-results"><span className="eyebrow">{search ? '搜索结果' : '快速前往'}</span>{works.filter(w => !search || `${w.title}${w.genre}`.includes(search)).map(w => <button key={w.id} onClick={() => {setModal(null); navigate(`editor/${w.id}`);}}><BookOpen size={19}/><span>{w.title}<small>{w.kind} · {w.genre}</small></span><ArrowUpRight size={16}/></button>)}{tools.filter(t => search && `${t.title}${t.desc}`.includes(search)).map(t => <button key={t.id} onClick={() => setModal({type:'tool',tool:t})}><Icon name={t.icon} size={19}/><span>{t.title}<small>AI 工具 · {t.category}</small></span><ArrowUpRight size={16}/></button>)}{workflows.filter(f => search && `${f.title}${f.desc}`.includes(search)).map(f => <button key={f.id} onClick={() => setModal({type:'workflow',flow:f})}><Workflow size={19}/><span>{f.title}<small>创作工作流</small></span><ArrowUpRight size={16}/></button>)}{search && ![...works.map(w=>w.title+w.genre),...tools.map(t=>t.title+t.desc),...workflows.map(f=>f.title+f.desc)].some(t=>t.includes(search)) && <Empty title="还没有找到" text="试试作品名称，或搜索“大纲”“灵感”。"/>}</div></>}
   {modal.type === 'help' && <><div className="modal-symbol"><CircleHelp/></div><h2>让创作顺畅一点</h2><p className="modal-desc">几个小提示，帮你更快进入写作状态。</p><div className="help-items"><div><kbd>⌘ K</kbd><span>快速查找作品与工具</span></div><div><BookOpen size={18}/><span>在「我的作品」新建或导入 TXT 文稿</span></div><div><Download size={18}/><span>编辑器右上角可导出完整作品</span></div><div><CheckCheck size={18}/><span>作品自动保存到本机服务，并保留浏览器缓存，建议定期导出备份</span></div></div><button className="button primary full" onClick={() => setModal(null)}>知道了，继续创作</button></>}
   {modal.type === 'notifications' && <><div className="modal-symbol"><Bell/></div><h2>消息通知</h2><div className="notice-item"><span className="notice-dot"/><div><h4>欢迎来到你的创作空间</h4><p>三部示例作品和精选 AI 工具已准备好。打开一本，试着写下你的第一句话。</p><small>今天</small></div></div><div className="notice-item"><CheckCircle2 size={19}/><div><h4>你的文字会被好好保存</h4><p>当前作品自动保存到本机服务，保留浏览器缓存，随时可以导出 TXT 文稿。</p><small>创作提示</small></div></div></>}
   {modal.type === 'account' && <><div className="profile-avatar">墨</div><h2>墨多多的创作空间</h2><p className="modal-desc">每一天，都离理想中的故事更近一点。</p><div className="profile-stats"><div><strong>{works.length}</strong><span>部作品</span></div><div><strong>{works.reduce((a,w)=>a+workWords(w),0).toLocaleString()}</strong><span>字已落笔</span></div><div><strong>{favorites.length}</strong><span>收藏工具</span></div></div><AccountAccess onClose={()=>setModal(null)}/><AccountBilling onOpen={()=>{setModal(null);billing.go('plans');}}/><div className="soft-notice"><CheckCheck size={17}/>当前使用本地创作空间，内容自动保存在本机服务，并保留浏览器缓存。</div><button className="button secondary full" onClick={()=>setModal({type:'settings'})}><Settings2 size={16}/>创作与数据设置、整库备份</button><button className="button primary full" onClick={() => {setModal(null);navigate('works');}}>回到我的作品<ArrowRight size={16}/></button></>}
   {modal.type === 'membership' && <><h2>会员与墨点</h2><p className="modal-desc">根据创作频率选择套餐，或按需购买墨点。</p><button className="button primary full" onClick={()=>{setModal(null);billing.go('plans');}}>查看套餐<ArrowRight size={16}/></button></>}
   {modal.type === 'lesson' && <><span className="eyebrow">墨多多 · 写作手记</span><h2>{modal.lesson.title}</h2><p className="modal-desc">{modal.lesson.desc}</p><article className="lesson-content">{modal.lesson.content.split('\n\n').map((p,i)=><p key={i}>{p}</p>)}</article><button className="button primary full" onClick={()=>setModal({type:'create'})}>把方法用在新故事里<Feather size={16}/></button></>}
  </section></div>}
  {toast && <div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}
 </>;
}

function PageHeading({ eyebrow, title, desc, children }) { return <div className="page-heading"><div><h1>{title}</h1>{desc && <p>{desc}</p>}</div><div className="heading-actions">{children}</div></div>; }
function SectionHeading({ title, desc, children }) { return <div className="section-heading"><div><h2>{title}</h2>{desc && <span>{desc}</span>}</div>{children}</div>; }

function ToolCard({ tool, favorite, onFavorite, onOpen }) { return <article className="tool-card"><div className="tool-card-top"><span className={`type-icon ${tool.color}`}><Icon name={tool.icon} size={22} strokeWidth={1.7}/></span><button className={cn('favorite-button',favorite&&'saved')} aria-label={favorite?'取消收藏':'收藏工具'} onClick={onFavorite}><Star size={17} fill={favorite?'currentColor':'none'}/></button></div><button className="tool-card-main" onClick={onOpen}><h3>{tool.title}</h3><p>{tool.desc}</p></button><div className="tool-card-bottom"><span>{tool.tags.map(t=><small key={t}>{t}</small>)}</span><button onClick={onOpen}>使用<ArrowUpRight size={13}/></button></div></article>; }
function WorkflowsPage({ setModal }) { const [filter,setFilter]=useState('全部工作流');return <><PageHeading eyebrow="STEP BY STEP, STORY BY STORY" title="创作工作流" desc="把创作拆成小步骤，让好故事自然而然发生。"/><div className="workflow-intro"><span className="workflow-intro-icon"><Workflow size={30}/></span><div><h3>少一点来回切换，多一点专注创作。</h3><p>串联灵感、大纲、正文与润色。每一步都能查看、修改，由你掌握故事的方向。</p></div><span className="soft-label">你始终是故事的作者</span></div><div className="pill-tabs flow-tabs">{['全部工作流','长篇创作','短篇创作','剧本改编','编辑优化'].map(t=><button className={cn(filter===t&&'active')} key={t} onClick={()=>setFilter(t)}>{t}</button>)}</div><div className="workflow-grid">{workflows.filter(f=>filter==='全部工作流'||f.type===filter).map(flow=><article className="workflow-card" key={flow.id}><div className="workflow-card-head"><span className={`type-icon ${flow.color}`}><Icon name={flow.icon} size={25}/></span><span className="category-tag">{flow.type}</span></div><h2>{flow.title}</h2><p>{flow.desc}</p><div className="flow-nodes">{flow.steps.map((s,i)=><React.Fragment key={s}><span>{s}</span>{i<flow.steps.length-1&&<ChevronRight size={12}/>}</React.Fragment>)}</div><div className="workflow-card-bottom"><span><Workflow size={14}/>{flow.steps.length} 个步骤 · 分步确认</span><button className="button secondary" onClick={()=>setModal({type:'workflow',flow})}>开始工作流<ArrowRight size={15}/></button></div></article>)}</div></>; }

function CreateForm({initial,onCreate}) {
 const [title,setTitle]=useState(initial.title||''); const [kind,setKind]=useState(initial.kind||'长篇小说'); const [genre,setGenre]=useState(initial.genre||'悬疑'); const [idea,setIdea]=useState(initial.idea||'');
 return <form onSubmit={e=>{e.preventDefault();if(title.trim())onCreate({title:title.trim(),kind,genre,idea});}}><div className="modal-symbol"><Feather size={25}/></div><span className="eyebrow">新的创作</span><h2>新建作品</h2><p className="modal-desc">设置名称与题材，创建后即可进入编辑器。</p><label className="field">作品名称<input autoFocus required maxLength={30} value={title} onChange={e=>setTitle(e.target.value)} placeholder="你的下一个好故事，叫什么？"/></label><label className="field">创作类型</label><div className="form-type-options">{['长篇小说','短篇故事','剧本'].map(t=><button type="button" key={t} onClick={()=>setKind(t)} className={cn(kind===t&&'selected')}>{t}{kind===t&&<Check size={14}/>}</button>)}</div><label className="field">题材方向<select value={genre} onChange={e=>setGenre(e.target.value)}>{['悬疑','言情','科幻','奇幻','都市','历史','治愈','其他'].map(t=><option key={t}>{t}</option>)}</select></label><label className="field">最初的灵感<span className="optional">选填</span><textarea value={idea} onChange={e=>setIdea(e.target.value)} placeholder="一个人物、一句话，或者一个你念念不忘的画面…" rows={3}/></label><button type="submit" className="button primary full">创建作品，开始落笔<ArrowRight size={17}/></button><p className="form-footnote">作品自动保存到本机服务，并保留浏览器缓存。</p></form>;
}

export function ToolDialog({tool,works,onFavorite,favorite,notify,setModal,onChange,initial={},createWork,getWork}) {
 const [workId,setWorkId]=useState(initial.workId||''),[selectedChapter,setSelectedChapter]=useState(initial.chapterId||''),[busy,setBusy]=useState(false),[pendingExample,setPendingExample]=useState('');
 const generation=useGeneration(),workspace=useWorkspace();const linked=works.find(w=>w.id===workId);const chapter=linked?.chapters.find(c=>c.id===selectedChapter)||linked?.chapters[0];
 const thread=useRevisionThread(`tool:${tool.id}:${workId||'free'}:${chapter?.id||'none'}`);const prompt=thread.prompt,result=thread.candidate?.text||'';
 const initialApplied=useRef(false);useEffect(()=>{if(!initialApplied.current){initialApplied.current=true;if(initial.prompt){if(prompt.trim()&&prompt!==initial.prompt)setPendingExample(initial.prompt);else thread.update({prompt:initial.prompt});}}},[]);
 const latest=useRef();latest.current={works,workId,chapterId:chapter?.id};
 const memory=linked?buildStoryContext(linked,{chapterId:chapter?.id,query:prompt,referenceIds:thread.referenceIds||[]}):{context:{},inputChars:0};
 const target=tool.id==='outline'?'outline':tool.id==='character'?'characters':['review','ideas','title'].includes(tool.id)?'notes':'text';
 const targetText=linked?(target==='outline'||target==='characters'?linked[target]||'':chapter?.text||''):'';
 const inputField=target==='notes'?'text':target;
 const meter=useTaskMeter(tool.id,{inputChars:prompt.length+targetText.length+(memory.inputChars||0)+(thread.continuing?result.length:0)});
 const useExample=example=>{if(prompt.trim()&&prompt!==example)setPendingExample(example);else thread.update({prompt:example});};
 const run=()=>meter.run(async()=>{
  setBusy(true);const prior=thread.continuing?thread.candidate:null;
  const anchor=linked?captureRevision({workId:linked.id,chapterId:chapter?.id,field:target,text:target==='text'?chapter?.text||'':linked[target]||''}):null;
  try{const generated=await generation.generate({task:tool.id,prompt:prior?`基于上一稿继续修改。\n本轮要求：${prompt}`:prompt,context:revisionContext(linked?{...memory.context,workId:linked.id,chapterId:chapter?.id,title:linked.title,genre:linked.genre,chapterTitle:chapter?.title,text:targetText,targetText,targetField:inputField,adoptionField:target}: {},prior,thread.versions,prompt),target:meter.outputChars,mode:meter.model},tool.output);thread.addCandidate(generated.text,{requirement:prompt,source:generated.source||generation.mode,anchor,task:tool.id});}finally{setBusy(false);}
 });
 const preview=()=>{
  const saved=thread.candidate,anchor=saved?.anchor;if(!linked||!anchor)return;
  const resolve=()=>{const current=latest.current,work=getWork?getWork(anchor.workId):workspace?workspace.client.entries.works.data.find(item=>item.id===anchor.workId&&!item.deletedAt):current.works.find(item=>item.id===anchor.workId),currentChapter=work?.chapters.find(item=>item.id===anchor.chapterId);return {work,chapter:currentChapter,current:{workId:current.workId,chapterId:current.chapterId,field:target,text:target==='text'?currentChapter?.text||'':work?.[target]||''}};};
  const live=resolve();if(!revisionMatches(anchor,live.current)){notify('关联文稿已改变，请基于当前稿重新生成后再采纳');return;}
  setModal({type:'draft-review',before:anchor.before,candidate:result,task:tool.title,source:saved.source,onRevise:text=>{thread.beginFollowup(text);setModal({type:'tool',tool,workId,chapterId:chapter?.id});},onApply:(text,mode)=>{
   const live=resolve();if(!revisionMatches(anchor,live.current)){notify('关联文稿已改变，请重新定位并生成候选');return;}
   const updated=applyDraft(anchor.before,text,mode);onChange(target==='text'?{...saveChapterVersion(live.work,live.chapter,'工具采纳前'),chapters:live.work.chapters.map(c=>c.id===live.chapter.id?{...c,text:updated}:c)}:{...live.work,[target]:updated});setModal(null);notify(target==='notes'?'已保存到创作笔记':'创作结果已保存到关联作品');
  }});
 };
 return <><div className="tool-dialog-heading"><span className={`type-icon ${tool.color}`}><Icon name={tool.icon} size={25}/></span><GenerationStatus generation={generation} busy={busy} onSettings={()=>setModal?.({type:'settings'})}/></div><h2>{tool.title}</h2>{thread.saveError&&<p role="alert">创作需求与候选未能保存，请复制内容备份。</p>}<p className="modal-desc">{tool.desc}</p><ToolGuide toolId={tool.id} onUseExample={useExample}/>{pendingExample&&<div className="revision-preview-note"><p>当前需求已有内容。确认后可替换成下面的示例：</p><p>{pendingExample}</p><button className="text-button" onClick={()=>{thread.update({prompt:pendingExample});setPendingExample('');}}>用此示例替换需求</button><button className="text-button" onClick={()=>setPendingExample('')}>保留当前需求</button></div>}<label className="field">关联作品<select aria-label="工具关联作品" disabled={busy} value={workId} onChange={e=>setWorkId(e.target.value)}><option value="">不关联，先试试灵感</option>{works.map(w=><option key={w.id} value={w.id}>{w.title}</option>)}</select></label>{linked&&<label className="field">编辑章节<select aria-label="工具引用章节" disabled={busy} value={chapter?.id||''} onChange={e=>setSelectedChapter(e.target.value)}>{linked.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>}{linked&&<><div className="context-notice"><BookOpen size={15}/>当前{inputField==='text'?'章节正文':inputField==='outline'?'作品总纲':'人物设定'}是本次{target==='notes'?'分析素材，结果可存入创作笔记':'编辑目标'}；其他资料由你选择引用。</div><ContextPicker work={linked} value={thread.referenceIds||[]} onChange={ids=>thread.update({referenceIds:ids})} prompt={prompt} chapterId={chapter?.id}/></>}<label className="field">{thread.continuing?'基于此稿继续修改的要求':'你的创作需求'}<textarea aria-label="工具创作需求" rows={3} value={prompt} onChange={e=>thread.update({prompt:e.target.value})} placeholder={thread.continuing?'说说上一稿还需要怎样调整…':'描述你的想法，或粘贴一段想要打磨的文字…'}/></label>{thread.continuing&&<div className="revision-followup">将以第 {thread.candidate?.id} 稿为基础，并带上历史创作要求。<button className="text-button" onClick={()=>thread.update({continuing:false})}>回到独立生成</button></div>}<TaskMeter meter={meter}/><div className="tool-dialog-actions"><button className="button secondary" onClick={onFavorite}><Star size={16} fill={favorite?'currentColor':'none'}/>{favorite?'已收藏':'收藏工具'}</button><button className="button primary" onClick={run} disabled={busy||(thread.continuing&&!prompt.trim())}>{busy?<LoaderCircle className="spin" size={16}/>:<Sparkles size={16}/>} {busy?'灵感正在酝酿…':thread.continuing?'提交本轮修改':result?'重新生成':generation.mode==='ai'?'开始生成':'生成示例'}</button></div>{result&&<div className="generated-result"><div><strong>创作参考 · 第 {thread.candidate.id} 稿</strong><button className="text-button" onClick={()=>{copyText(result).then(()=>notify('已复制创作参考')).catch(()=>notify('复制未完成，请手动选择并复制文字'));}}><Copy size={14}/>复制</button></div><textarea aria-label="创作参考，可编辑" value={result} onChange={e=>thread.editCandidate(e.target.value)} rows={9}/><small>{thread.candidate.source==='ai'?'根据你的输入生成，请检查后使用。':'示例内容，可以编辑后使用。'}</small><button className="button secondary full revision-continue-button" disabled={busy} onClick={()=>thread.beginFollowup()}>基于此稿继续修改<MessagesSquare size={14}/></button><RevisionHistory thread={thread} disabled={busy}/>{linked&&<button className="button secondary full" onClick={preview}>预览并保存到关联作品<WandSparkles size={14}/></button>}{!linked&&createWork&&<button className="button secondary full" onClick={()=>createWork({title:tool.title+' · 创作参考',kind:'短篇故事',genre:'其他',text:result,idea:thread.candidate.requirement})}>保存为新作品<BookOpen size={15}/></button>}</div>}</>;
}

export function WorkflowDialog({flow,works,createWork,initial={},onChange,setModal,notify}) {
 const [allDrafts,setAllDrafts]=useCollection('workflows',[]);
 const [draft]=useState(()=>allDrafts.find(item=>(item.id===flow.id||item.flowId===flow.id)&&(!initial.workId||item.workId===initial.workId)&&(!initial.chapterId||!item.chapterId||item.chapterId===initial.chapterId)));
 const [draftId,setDraftId]=useState(draft?.id||(initial.workId?`${flow.id}-${initial.workId}${initial.chapterId?'-'+initial.chapterId:''}`:flow.id));
 const savedDrafts=allDrafts.filter(item=>item.id===flow.id||item.flowId===flow.id);
 const [step,setStep]=useState(draft?.step??-1);const [idea,setIdea]=useState(draft?.idea||'');const [title,setTitle]=useState(draft?.title||'');const [content,setContent]=useState(draft?.content||'');const [results,setResults]=useState(draft?.results||{});const [busy,setBusy]=useState(false);const [workId,setWorkId]=useState(initial.workId||draft?.workId||'');const [saveError,setSaveError]=useState(false);
 const [chapterId,setChapterId]=useState(draft?.chapterId||initial.chapterId||'');
 const generation=useGeneration();const sourceWork=works.find(w=>w.id===workId);const sourceChapter=sourceWork?.chapters.find(c=>c.id===chapterId)||sourceWork?.chapters[0];
 useEffect(()=>{const drafts=allDrafts;setSaveError(!setAllDrafts([{id:draftId,flowId:flow.id,step,idea,title,content,results,workId,chapterId,updatedAt:new Date().toISOString()},...drafts.filter(d=>d.id!==draftId)]));},[draftId,step,idea,title,content,results,workId,chapterId]);
 const editContent=value=>{setContent(value);setResults(prev=>Object.fromEntries(Object.entries(prev).filter(([index])=>Number(index)<=step)));};
 const nextLabel=flow.steps[step+1]||'';
 const nextToolId=flow.type==='编辑优化'?(/润色/.test(nextLabel)?'polish':'review'):/人物/.test(nextLabel)?'character':/大纲|规划|结构/.test(nextLabel)?'outline':/润色/.test(nextLabel)?'polish':/检查|建议|分析/.test(nextLabel)?'review':/对白/.test(nextLabel)?'dialogue':step<0?'ideas':'continue';
 const meter=useTaskMeter(nextToolId,{inputChars:idea.length+content.length});
 const run=()=>{const next=step+1;const saved={...results,...(step>=0?{[step]:content}:{})};if(saved[next]!==undefined){setResults(saved);setStep(next);setContent(saved[next]);return;}return meter.run(async()=>{setBusy(true);setResults(saved);try{const result=await generation.generate({task:nextToolId,prompt:idea,stage:nextLabel,previous:Object.fromEntries(Object.entries(saved).map(([index,value])=>[flow.steps[Number(index)],value])),context:{title,workId:sourceWork?.id,chapterId:flow.type==='编辑优化'?sourceChapter?.id:undefined,source:sourceWork?{title:sourceWork.title,outline:sourceWork.outline,characters:sourceWork.characters,text:flow.type==='编辑优化'?sourceChapter?.text||'':sourceWork.chapters.map(c=>c.text).join('\n\n')}:null},target:meter.outputChars,mode:meter.model},tools.find(t=>t.id===nextToolId).output);setStep(next);setContent(result.text);}finally{setBusy(false);}});};
 const writeBack=()=>{if(!sourceWork)return;const chapter=sourceChapter;setModal({type:'draft-review',before:chapter.text,candidate:content,task:flow.title,source:generation.source,onApply:(text,mode)=>{onChange({...saveChapterVersion(sourceWork,chapter,'工作流采纳前'),chapters:sourceWork.chapters.map(c=>c.id===chapter.id?{...c,text:applyDraft(chapter.text,text,mode)}:c)});setAllDrafts(prev=>prev.filter(d=>d.id!==draftId));setModal(null);notify('工作流结果已采纳到原章节');}});};
 const saveFlow=()=>{const saved={...results,[step]:content};const entries=Object.entries(saved).map(([index,text])=>({label:flow.steps[Number(index)],text}));setAllDrafts(prev=>prev.filter(d=>d.id!==draftId));createWork({title:title||'未命名的故事',kind:flow.type==='剧本改编'?'剧本':flow.type==='短篇创作'?'短篇故事':'长篇小说',genre:sourceWork?.genre||'其他',idea:idea||'从创作工作流诞生的新故事',outline:[idea,...entries.filter(e=>!/正文|人物|润色|对白/.test(e.label)).map(e=>`${e.label}\n${e.text}`)].filter(Boolean).join('\n\n'),characters:entries.filter(e=>/人物/.test(e.label)).map(e=>e.text).join('\n\n'),text:entries.filter(e=>/正文|分场剧本|润色|对白/.test(e.label)).map(e=>e.text).at(-1)||''});};
 return <><span className="eyebrow">{flow.type} · 分步创作</span><GenerationStatus generation={generation} busy={busy}/>{saveError&&<p role="alert">草稿未能保存，请复制当前内容备份。</p>}<h2>{flow.title}</h2>{savedDrafts.length>1&&<label className="field">切换已保存草稿<select aria-label="工作流草稿" disabled={busy} value={draftId} onChange={e=>{const d=savedDrafts.find(v=>v.id===e.target.value);setDraftId(d.id);setStep(d.step);setIdea(d.idea);setTitle(d.title);setContent(d.content);setResults(d.results);setWorkId(d.workId||'');setChapterId(d.chapterId||'');}}>{savedDrafts.map(d=><option key={d.id} value={d.id}>{d.title||'未命名的故事'} · {d.id===flow.id?'当前草稿':'恢复的草稿'}</option>)}</select></label>}<p className="modal-desc">每一步都可以修改，故事的方向由你决定。</p><div className="workflow-stepper">{flow.steps.map((s,i)=><div key={s} className={cn(step===i&&'current',step>i&&'done')}><span>{step>i?<Check size={13}/>:i+1}</span><small>{s}</small></div>)}</div>{step<0?<><label className="field">这次故事的名字<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="暂时叫《未命名的故事》"/></label><label className="field">先放进一颗灵感种子<textarea rows={5} value={idea} onChange={e=>{setIdea(e.target.value);setResults({});}} placeholder="比如：一个可以听到旧物记忆的修复师，收到了一件属于未来的物品。"/></label><label className="field">关联原作<select value={workId} onChange={e=>{setWorkId(e.target.value);setChapterId('');setResults({});}}><option value="">不关联作品</option>{works.map(w=><option key={w.id} value={w.id}>{w.title}</option>)}</select></label>{sourceWork&&flow.type==='编辑优化'&&<label className="field">改稿章节<select aria-label="工作流引用章节" value={sourceChapter?.id||''} onChange={e=>{setChapterId(e.target.value);setResults({});}}>{sourceWork.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>}<div className="soft-notice"><Sparkles size={17}/>{generation.mode==='ai'?'每一步会结合原作及此前结果生成。':'示例模式返回预置内容，草稿会自动保留。'}</div></>:<label className="field">第 {step+1} 步 · {flow.steps[step]}<textarea rows={12} value={content} onChange={e=>editContent(e.target.value)}/></label>}{step<flow.steps.length-1&&(results[step+1]!==undefined?<p className="meter-free-note"><CheckCircle2 size={14}/>下一步已有结果，恢复不扣点。</p>:<TaskMeter meter={meter}/>)}<div className="modal-bottom-note"><span>{step>0?<button className="text-button" disabled={busy} onClick={()=>{setResults(prev=>({...prev,[step]:content}));setStep(step-1);setContent(results[step-1]||'');}}><ChevronLeft size={13}/>返回上一步</button>:step===0?<button className="text-button" disabled={busy} onClick={()=>{setResults(prev=>({...prev,[step]:content}));setStep(-1);}}>返回初始设定</button>:'确认这一阶段后，再进入下一步。'}</span>{step===flow.steps.length-1?<span className="workflow-finish-actions">{sourceWork&&flow.type==='编辑优化'&&onChange&&<button className="button secondary" onClick={writeBack}>预览并更新原章节</button>}<button className="button primary" onClick={saveFlow}>保存为新作品<Check size={16}/></button></span>:<button className="button primary" disabled={busy} onClick={run}>{busy?<LoaderCircle className="spin" size={16}/>:<ArrowRight size={16}/>} {busy?'正在准备…':step<0?'开始第一步':'确认并继续'}</button>}</div></>;
}

const lessons=[{title:'第一章，怎样让人读下去？',category:'创作入门',time:'5 分钟',color:'green',desc:'给读者一个具体的人、一个眼前的问题，以及继续往下读的理由。',content:'先让故事发生。与其用很长的篇幅解释世界，不如让主角先面对一个具体问题：门缝里突然出现一封信，末班车驶向一个陌生的站台，老友说了一句不该知道的话。\n\n让读者知道主角想要什么。这个目标不一定宏大，但需要清楚。想回家、想保住一家店、想确认一个消息，都可以成为故事的起点。\n\n给信息留一点空白。一个好开篇并不急着回答所有问题。呈现足够的线索，让读者能够猜测，再用一个小小的意外推动下一页。\n\n现在，试着用三百字写一个场景：主角正在完成一件普通的事，一个意料之外的细节打断了他。'},{title:'比“完美”更重要的人物细节',category:'人物塑造',time:'6 分钟',color:'amber',desc:'从一个小习惯、一处矛盾，找到人物鲜活的入口。',content:'人物首先是一个有欲望的人。他想得到什么？为什么现在必须行动？如果一无所获，他会失去什么？\n\n让性格出现在选择里。不要只告诉读者“她很勇敢”，让她在害怕的时候，仍然伸手推开那扇门。\n\n矛盾让人物有层次。一个严肃的人可能会认真给流浪猫取名字，一个看似自信的人可能反复删除同一句消息。\n\n为角色写一个秘密，再写一个连他自己都不愿承认的愿望。让这两者在故事里慢慢靠近。'},{title:'让 AI 帮忙，保留自己的声音',category:'AI 共创',time:'4 分钟',color:'purple',desc:'把 AI 当成能一起讨论的搭子，让每一次采纳都有你的判断。',content:'先确定你想解决的具体问题。是开篇节奏太慢，还是对白缺少人物特点？越清楚的任务，越容易得到有用的参考。\n\n提供作品上下文。告诉 AI 人物的目标、当前的处境、你不希望改变的设定，并附上一小段你满意的文字作为语气参考。\n\n一次只处理一个层面。先讨论结构，再修改段落，最后打磨词句。这样你能知道每次修改带来了什么变化。\n\n保留自己的选择。对照原稿阅读，留下真正服务于故事的部分。你始终是作品的作者。'}];
function LearnPage({setModal,notify}) {
 const [evaluating,setEvaluating]=useState(false);
 const runCase=value=>{const tool=tools.find(tool=>tool.id===value.task);if(tool)setModal({type:'tool',tool,prompt:[value.prompt,value.sourceText&&`案例原文与设定：\n${value.sourceText}`].filter(Boolean).join('\n\n')});};
 return <><div className="page-heading"><div><h1>{evaluating?'写作效果评估':'写作课堂'}</h1><p>{evaluating?'用相同案例对照候选，记录作者评分、实际修改与已知用量。':'从开篇、人物到表达，让每一次落笔更有把握。'}</p></div><button className="button secondary" onClick={()=>setEvaluating(!evaluating)}>{evaluating?'返回写作手记':'打开固定案例评估'}<ArrowRight size={15}/></button></div>{evaluating?<WritingEvaluation onRunCase={runCase} notify={notify}/>:<><div className="learning-hero"><span className="eyebrow">写作是一场漫长而有趣的练习</span><h2>好故事的背后，<br/>是一次又一次认真落笔。</h2><Feather size={110} strokeWidth={.65}/></div><SectionHeading title="写作手记" desc="不急着成为大师，先享受今天的创作"/><div className="lesson-grid">{lessons.map((l,i)=><button className="lesson-card" key={l.title} onClick={()=>setModal({type:'lesson',lesson:l})}><div className={`lesson-cover ${l.color}`}><span>写作手记</span><strong>0{i+1}</strong><Feather size={48} strokeWidth={1}/></div><div><span className="eyebrow">{l.category} · {l.time}</span><h3>{l.title}</h3><p>{l.desc}</p><span className="text-button">读一读<ArrowRight size={15}/></span></div></button>)}</div></>}</>;
}

export function Editor({work,onChange,onBack,notify,setModal,saveError=false,openVideo,openSubmission}) {
 const [chapterId,setChapterId]=useState(()=>work.chapters.find(ch=>ch.id===work.lastEditedChapterId)?.id||work.chapters[0]?.id);const [tab,setTab]=useState('正文');const [aiTab,setAiTab]=useState('AI 助手');const [busy,setBusy]=useState(false);const [focus,setFocus]=useState(false);const [showAI,setShowAI]=useState(() => typeof window === 'undefined' || window.innerWidth > 1180);const [fontSize,setFontSize]=useState(17);const [saveState,setSaveState]=useState('已自动保存');const [aiAction,setAiAction]=useState('续写故事');const [customChapter,setCustomChapter]=useState(false);const [chapterName,setChapterName]=useState('');const [showChapters,setShowChapters]=useState(false);const manuscriptRef=useRef();const [lastAdoption,setLastAdoption]=useState(null);const [selection,setSelection]=useState(null),[selectionIntent,setSelectionIntent]=useState('润色');
 const generation=useGeneration();const workspace=useWorkspace();
 const displayedSave=workspace?workspaceFeedback(workspace).label:saveState;
 useEffect(()=>{generation.cancel();setSelection(null);},[chapterId,tab]);
 const chapter=work.chapters.find(ch=>ch.id===chapterId)||work.chapters[0];
 useEffect(()=>{if(!work.chapters.some(ch=>ch.id===chapterId))setChapterId(work.chapters[0].id);},[work.chapters,chapterId]);
 useEffect(()=>{const field=manuscriptRef.current;if(field){field.style.height='auto';field.style.height=`${Math.max(550,field.scrollHeight)}px`;}},[chapter?.text,work.outline,work.characters,tab,chapterId,fontSize,showAI,focus]);
 const field=tab==='大纲'?'outline':tab==='人物'?'characters':'notes';
 const activeField=tab==='正文'?'text':field,activeText=tab==='正文'?chapter.text:(work[field]||'');
 const scopeKey=`editor:${work.id}:${chapter.id}:${tab}:${selection?`${selection.revision}:${selection.start}:${selection.end}`:'whole'}`;
 const thread=useRevisionThread(scopeKey),prompt=thread.prompt,answer=thread.candidate?.text||'',referenceIds=thread.referenceIds||[];
 const latest=useRef();latest.current={work,chapter,tab,scopeKey,activeField,activeText};
 const memory=buildStoryContext(work,{chapterId:chapter.id,query:prompt,referenceIds});
 const captureSelection=event=>{if(tab!=='正文')return;const node=event.target,start=node.selectionStart,end=node.selectionEnd;if(Number.isInteger(start)&&end>start)setSelection(captureRevision({workId:work.id,chapterId:chapter.id,text:chapter.text,start,end}));else setSelection(null);};
 const selectionCurrent=!selection||revisionMatches(selection,{workId:work.id,chapterId:chapter.id,field:'text',text:chapter.text});
 const relocate=()=>{setSelection(null);manuscriptRef.current?.focus?.();notify('请在当前正文重新选中文字，再生成选段候选');};

 const save=value=>{setLastAdoption(null);setSaveState('保存中…');if(tab==='正文'){onChange({...work,chapters:work.chapters.map(ch=>ch.id===chapter.id?{...ch,text:value}:ch)});}else onChange({...work,[field]:value});setTimeout(()=>setSaveState('已自动保存'),400);};
 const addChapter=()=>{const id=uid();onChange({...work,chapters:[...work.chapters,{id,title:chapterName.trim()||`第${work.chapters.length+1}章 · 未命名章节`,text:''}]});setChapterId(id);setTab('正文');setChapterName('');setCustomChapter(false);setShowChapters(false);notify('新章节已创建');};
 const taskId=selection?'polish':aiAction==='润色文字'?'polish':aiAction==='检查逻辑'?'review':aiAction==='灵感脑洞'?'ideas':'continue';
 const meter=useTaskMeter(taskId,{inputChars:prompt.length+(selection?.selectedText?.length||activeText.length)+(memory.inputChars||0)+(thread.continuing?answer.length:0)});
 const generate=(options={})=>{
  if(selection&&!selectionCurrent){notify('原稿已经改变，请重新定位选段后生成');return;}
  return meter.run(async()=>{
   setBusy(true);const intent=options.selectionAction||selectionIntent,task=selection?'polish':taskId,prior=thread.continuing?thread.candidate:null;
   const targetText=selection?selection.selectedText:activeText;
   const anchor=task==='review'?captureRevision({workId:work.id,chapterId:chapter.id,field:'notes',text:work.notes||''}):selection||captureRevision({workId:work.id,chapterId:chapter.id,field:activeField,text:activeText});
   const requirement=selection?`只${intent}当前选段，保留叙事视角、人物关系和事实。仅输出修改后的选段，不输出前后文。${prompt?`\n作者要求：${prompt}`:''}`:prompt;
   try{
    const result=await generation.generate({task,prompt:prior?`基于上一稿继续修改。\n本轮要求：${requirement}`:requirement,context:revisionContext({...memory.context,workId:work.id,chapterId:chapter.id,title:work.title,genre:work.genre,chapterTitle:chapter.title,text:targetText,targetText,targetField:activeField,...(selection?{selection:{text:selection.selectedText,start:selection.start,end:selection.end,before:selection.before.slice(Math.max(0,selection.start-240),selection.start),after:selection.before.slice(selection.end,selection.end+240)},instruction:'只修改选段，前后文仅用于理解语境。'}:{})},prior,thread.versions,requirement),target:meter.outputChars,mode:meter.model},tools.find(t=>t.id===task).output);
    thread.addCandidate(result.text,{requirement,source:result.source||generation.mode,anchor,selection:Boolean(selection),scopeKey,task,action:selection?`选段${intent}`:aiAction});
   }finally{setBusy(false);}
  });
 };
 const candidateMatches=candidate=>{
  const live=latest.current,anchor=candidate?.anchor;
  return Boolean(anchor&&live.scopeKey===candidate.scopeKey&&revisionMatches(anchor,{workId:live.work.id,chapterId:live.chapter.id,field:anchor.field,text:anchor.field==='text'?live.chapter.text:live.work[anchor.field]||''}));
 };
 const reviewCandidate=()=>{
  const candidate=thread.candidate;if(!candidateMatches(candidate)){notify('原稿或章节已改变，请重新定位并生成候选后再采纳');return;}
  const anchor=candidate.anchor,before=candidate.selection?anchor.selectedText:anchor.before;
  setModal({type:'draft-review',before,candidate:answer,selection:candidate.selection,defaultMode:candidate.selection?'replace':'append',task:candidate.task==='review'?'审稿建议 · 保存到笔记':candidate.action,source:candidate.source,onRevise:text=>{thread.beginFollowup(text);setModal(null);},onApply:(text,mode)=>{
   if(!candidateMatches(candidate)){notify('原稿或章节已改变，请重新定位并生成候选');return;}
   const live=latest.current,current={workId:live.work.id,chapterId:live.chapter.id,field:anchor.field,text:anchor.field==='text'?live.chapter.text:live.work[anchor.field]||''};
   const next=candidate.selection?replaceRevisionSelection(anchor,text,current):applyDraft(anchor.before,text,mode);
   if(anchor.field==='text')onChange({...saveChapterVersion(live.work,live.chapter,'AI 采纳前'),chapters:live.work.chapters.map(item=>item.id===live.chapter.id?{...item,text:next}:item)});
   else onChange({...live.work,[anchor.field]:next});
   setLastAdoption({field:anchor.field,chapterId:anchor.chapterId,text:anchor.before,appliedText:next});setModal(null);notify(candidate.task==='review'?'审稿建议已保存到创作笔记，正文保持原样':'已采纳到文稿，可撤销本次修改');
  }});
 };
 const undoAdoption=()=>{
  if(!lastAdoption)return;const previous=lastAdoption,live=latest.current.work,current=previous.field==='text'?live.chapters.find(item=>item.id===previous.chapterId)?.text:live[previous.field]||'';
  if(current!==previous.appliedText){notify('采纳后文稿又有修改，请从版本记录中恢复，避免覆盖新内容');return;}
  if(previous.field==='text')onChange({...live,chapters:live.chapters.map(item=>item.id===previous.chapterId?{...item,text:previous.text}:item)});else onChange({...live,[previous.field]:previous.text});
  setLastAdoption(null);notify('已恢复采纳前的文稿');
 };
 const exportWork=()=>{downloadText(`${work.title}.txt`,`${work.title}\n\n${work.chapters.map(ch=>`${ch.title}\n\n${ch.text}`).join('\n\n')}`);notify('完整作品已导出为 TXT');};
 return <div className={cn('editor-app commercial-editor',focus&&'focus-mode')}><header className="editor-header"><div><button className="icon-button" aria-label="返回作品" onClick={onBack}><ArrowLeft size={20}/></button><button className="icon-button editor-mobile-chapters" aria-label="打开章节目录" onClick={()=>{setShowChapters(!showChapters);if(window.innerWidth<=1000)setShowAI(false);}}><Menu size={19}/></button><span className="editor-header-divider"/><Brand small/><button className="editor-book-name" onClick={()=>setModal({type:'work-details',work})}>{work.title}</button><span className="category-tag">{work.kind}</span></div><div><WorkspaceStatus/><button className="icon-button" aria-label="生成章节规划" title="生成章节规划" onClick={()=>setModal({type:'chapter-plan',workId:work.id})}><ListTree size={17}/></button>{videoEnabled&&openVideo&&<button className="icon-button" aria-label="当前章节转分镜" title="当前章节转分镜" onClick={()=>openVideo(work,chapter)}><Clapperboard size={17}/></button>}{openSubmission&&<button className="icon-button" aria-label="准备投稿" title="准备投稿" onClick={()=>openSubmission(work)}><Send size={17}/></button>}<span className="save-indicator"><CheckCheck size={14}/>{saveError?'缓存保存未完成':displayedSave}</span><button className="icon-button" aria-label="章节版本记录" title="章节版本记录" onClick={()=>setModal({type:'versions',chapterId:chapter.id})}><Clock3 size={17}/></button><button className="icon-button" aria-label="创作与数据设置" onClick={()=>setModal({type:'settings'})}><Settings2 size={17}/></button>{lastAdoption&&<button className="undo-adoption" onClick={undoAdoption}><RefreshCw size={13}/>撤销采纳</button>}<button className="icon-button" aria-label={focus?'退出专注模式':'专注模式'} onClick={()=>setFocus(!focus)}><Maximize2 size={17}/></button><button className="button secondary small-button" aria-label="导出作品" title="导出作品" onClick={exportWork}><Download size={15}/>导出作品</button><button className="button primary small-button" aria-pressed={showAI} onClick={()=>{setShowAI(!showAI);setShowChapters(false);setFocus(false);}}><Sparkles size={15}/>AI 助手</button></div></header>
  <div className="editor-body">{showAI&&<button className="ai-scrim" aria-label="关闭 AI 助手" onClick={()=>setShowAI(false)}/>} {showChapters&&<button className="chapter-scrim" aria-label="关闭章节目录" onClick={()=>setShowChapters(false)}/>}<aside className={cn("chapter-sidebar",showChapters&&"chapter-open")}><div className="chapter-book"><BookCover work={work}/><h3>{work.title}</h3><span>{workWords(work).toLocaleString()} 字 · {work.chapters.length} 章</span></div><div className="editor-nav-tabs">{['正文','大纲','人物','笔记'].map(t=><button key={t} className={cn(tab===t&&'active')} onClick={()=>{setTab(t);setShowChapters(false);}}>{t}</button>)}</div><div className="chapter-list-heading"><span>{tab==='正文'?'章节目录':tab==='大纲'?'故事规划':'人物资料'}</span>{tab==='正文'&&<button className="icon-button" aria-label="管理章节" title="管理章节" onClick={()=>setModal({type:'chapters',chapterId:chapter.id})}><Settings2 size={16}/></button>}{tab==='正文'&&<button className="icon-button" aria-label="添加章节" onClick={()=>setCustomChapter(true)}><Plus size={17}/></button>}</div>{tab==='正文'?<div className="chapter-list">{work.chapters.map((ch,i)=><button key={ch.id} onClick={()=>{setChapterId(ch.id);setShowChapters(false);}} className={cn(chapter.id===ch.id&&'active')}><FileText size={15}/><span>{ch.title}<small>{wordCount(ch.text)} 字</small></span></button>)}{customChapter?<form className="new-chapter-form" onSubmit={e=>{e.preventDefault();addChapter();}}><input autoFocus aria-label="新章节名称" placeholder="新章节名称" value={chapterName} onChange={e=>setChapterName(e.target.value)}/><div><button type="button" onClick={()=>setCustomChapter(false)}>取消</button><button type="submit">添加</button></div></form>:<button className="add-chapter" onClick={()=>setCustomChapter(true)}><Plus size={15}/>新建章节</button>}</div>:<div className="chapter-list"><button className="active"><ListTree size={15}/><span>{tab==='大纲'?'作品总纲':tab==='人物'?'角色设定':'审稿与创作笔记'}<small>随时补充与修改</small></span></button></div>}<div className="chapter-side-bottom"><span className="status-dot"/>你的文字，正在生长</div></aside>
   <section className="writing-area"><div className="editor-toolbar"><div className="editor-path"><span>{work.title}</span><ChevronRight size={12}/><strong>{tab==='正文'?'正文':tab==='大纲'?'作品大纲':tab==='人物'?'人物设定':'创作笔记'}</strong></div><div><button className="icon-button" aria-label="减小字号" onClick={()=>setFontSize(Math.max(14,fontSize-1))}><span className="font-control">A−</span></button><span className="font-size">{fontSize}</span><button className="icon-button" aria-label="增大字号" onClick={()=>setFontSize(Math.min(25,fontSize+1))}><span className="font-control">A+</span></button><span className="editor-header-divider"/><button className="icon-button" aria-label="显示或隐藏 AI 面板" aria-pressed={showAI} onClick={()=>{setShowAI(!showAI);setShowChapters(false);setFocus(false);}}><PanelRightClose size={17}/></button></div></div><div className="manuscript"><div className="manuscript-inner">{tab==='正文'?<input className="chapter-title-input" aria-label="章节标题" value={chapter.title} onChange={e=>onChange({...work,chapters:work.chapters.map(ch=>ch.id===chapter.id?{...ch,title:e.target.value}:ch)})}/>:<h1>{tab==='大纲'?'故事的骨架':tab==='人物'?'让人物活起来':'创作笔记'}</h1>}{tab==='正文'&&chapter.plan&&<details className="chapter-plan-note"><summary>本章创作规划</summary><p>{chapter.plan}</p></details>}<div className="chapter-writing-meta"><span>{tab==='正文'?`${wordCount(chapter.text)} 字`:'每一个设定，都是故事的一部分'}</span><span>浏览器缓存 · 本机持久保存</span></div><textarea ref={manuscriptRef} className="manuscript-text" aria-label={tab==='正文'?'章节正文':tab==='大纲'?'作品大纲':tab==='人物'?'人物设定':'创作笔记'} style={{fontSize:`${fontSize}px`}} value={tab==='正文'?chapter.text:(work[field]||'')} onChange={e=>save(e.target.value)} onSelect={captureSelection} placeholder={tab==='正文'?'故事，就从这一行开始。\n\n写下你脑海里的第一个画面…':tab==='大纲'?'记录主线、关键转折和每一卷的目标。':tab==='人物'?'给人物一个名字，再给他一个不得不行动的理由。':'记录审稿建议、修改计划、伏笔与创作想法。'}/>{selection&&<div className="selection-edit-bar"><strong>已选中 {selection.selectedText.length} 字 · 只修改此处</strong><p>{selection.selectedText}</p>{!selectionCurrent&&<p className="revision-stale" role="alert">正文已改变，请重新定位选段。</p>}<div>{['润色','扩写','缩写'].map(intent=><button className="button secondary" disabled={busy||!selectionCurrent} key={intent} onClick={()=>{setSelectionIntent(intent);setShowAI(true);generate({selectionAction:intent});}}>选段{intent}</button>)}<button className="text-button" onClick={relocate}>重新定位选段</button><button className="text-button" onClick={()=>setSelection(null)}>取消选段</button></div></div>}<div className="manuscript-end"><span/>未完，待续<span/></div></div></div><footer className={cn("editor-status",saveError&&"save-error")}><span><span className="status-dot"/>{saveError?'本地保存失败，请导出备份':'本地自动保存'}</span><span>本章 {wordCount(chapter.text)} 字 <i/>全书 {workWords(work)} 字</span><button onClick={()=>setFocus(!focus)}>{focus?'退出专注':'进入专注'}<Maximize2 size={12}/></button></footer></section>
   {showAI&&<aside className="ai-panel"><div className="ai-panel-tabs">{['AI 助手','工具箱','工作流'].map(t=><button key={t} onClick={()=>setAiTab(t)} className={cn(aiTab===t&&'active')}>{t}</button>)}</div>{aiTab==='AI 助手'?<><div className="ai-welcome"><div className="ai-avatar"><Sparkles size={22}/></div><h3>故事卡住了？一起想想。</h3><p>我在这里，陪你找回落笔的灵感。</p><GenerationStatus generation={generation} busy={busy} onSettings={()=>setModal({type:'settings'})}/></div><div className="ai-context"><span><BookOpen size={14}/>{selection?'选中的正文':'当前编辑区域'}是本次编辑目标</span><p className="revision-preview-note">附加资料由你选择引用，未选资料不会自动带入。</p><ContextPicker work={work} value={referenceIds} onChange={ids=>thread.update({referenceIds:ids})} prompt={prompt} chapterId={chapter.id}/><div><button className="text-button" onClick={()=>setModal({type:'story-memory',workId:work.id,chapterId:chapter.id})}>整理故事记忆</button><button className="text-button" onClick={()=>setModal({type:'chapter-queue',workId:work.id,chapterId:chapter.id})}>连续章节写作</button></div></div><div className="ai-actions">{[{name:'续写故事',icon:Feather},{name:'润色文字',icon:WandSparkles},{name:'检查逻辑',icon:ScanText},{name:'灵感脑洞',icon:Lightbulb}].map(a=><button key={a.name} className={cn(aiAction===a.name&&'active')} onClick={()=>setAiAction(a.name)}><a.icon size={16}/>{a.name}</button>)}</div>{thread.saveError&&<p role="alert">创作需求与候选未能保存，请复制内容备份。</p>}<div className="ai-answer-area">{busy?<div className="ai-thinking"><LoaderCircle className="spin" size={18}/>正在酝酿一个好想法…</div>:answer?<div className="ai-answer"><div><Sparkles size={14}/>创作参考</div><textarea className="revision-answer-text" aria-label="编辑器候选内容" value={answer} rows={8} onChange={e=>thread.editCandidate(e.target.value)}/><div className="answer-actions"><button onClick={()=>{copyText(answer).then(()=>notify('已复制候选文字')).catch(()=>notify('复制未完成，请手动选择并复制文字'));}}><Copy size={14}/>复制</button><button onClick={reviewCandidate}><WandSparkles size={14}/>预览并采纳</button></div><small>{thread.candidate.source==='ai'?'AI 生成内容，请核对后采纳。':'示例内容，可编辑后使用。'}</small>{!candidateMatches(thread.candidate)&&<p className="revision-stale" role="alert">原稿或定位已经改变，请重新生成候选。</p>}<button className="button secondary revision-continue-button" disabled={busy} onClick={()=>thread.beginFollowup()}>基于此稿继续修改</button><RevisionHistory thread={thread} disabled={busy}/></div>:<div className="ai-idle"><span>✧</span><p>选择一个任务，写下你的要求。<br/>先预览，再决定是否采纳。</p></div>}</div>{thread.continuing&&<div className="revision-followup">将基于第 {thread.candidate?.id} 稿继续修改，并带上历史要求。<button className="text-button" onClick={()=>thread.update({continuing:false})}>回到独立生成</button></div>}<TaskMeter meter={meter} compact/><div className="ai-prompt-box"><textarea aria-label="给 AI 的创作要求" placeholder={thread.continuing?'说说这一稿还需要怎样调整…':'说说你的想法，或选择上方的创作任务…'} rows={3} value={prompt} onChange={e=>thread.update({prompt:e.target.value})}/><div><span>{thread.continuing?'继续修改':selection?`选段${selectionIntent}`:aiAction} · {generation.mode==='ai'?'真实 AI':'示例模式'}</span><button aria-label={generation.mode==='ai'?'生成创作内容':'生成创作示例'} onClick={generate} disabled={busy||(thread.continuing&&!prompt.trim())||!selectionCurrent}>{busy?<LoaderCircle className="spin" size={15}/>:<ArrowRight size={17}/>}</button></div></div><span className="ai-disclaimer">灵感由 AI 辅助，故事由你决定。</span></>:<div className="editor-tool-list">{aiTab==='工具箱'?tools.map(t=><button key={t.id} onClick={()=>setModal({type:'tool',tool:t,workId:work.id,chapterId:chapter.id})}><span className={`type-icon ${t.color}`}><Icon name={t.icon} size={19}/></span><span><strong>{t.title}</strong><small>{t.category}</small></span><ChevronRight size={14}/></button>):workflows.map(f=><button key={f.id} onClick={()=>setModal({type:'workflow',flow:f,workId:work.id,chapterId:chapter.id})}><span className={`type-icon ${f.color}`}><Workflow size={19}/></span><span><strong>{f.title}</strong><small>{f.steps.length} 个步骤</small></span><ChevronRight size={14}/></button>)}</div>}</aside>}
  </div>
 </div>;
}
